process_files() {
    local CURRENT_DOSSIER="$1"
    
    CURRENT_DOSSIER="${CURRENT_DOSSIER%/}"
    
    for dir in "${CURRENT_DOSSIER}"; do
        [ -d "$dir" ] || continue
    
        for report in "$dir"/**/*.kreport; do
            [ -f "$report" ] || continue
            
            parent_dir=$(basename "$(dirname "$report")")
            
            sample_name=$(basename "$report" .kreport)
            sample_base=$(echo "$sample_name" | sed -E 's/^Unmapped_//; s/_[0-9]+\.[0-9]+$//')
            
            if [[ "$sample_base" =~ ^GLP2_(.+) ]]; then sample_clean="${BASH_REMATCH[1]}"
            elif [[ "$sample_base" =~ ^([0-9]+)[A-Z]+ ]]; then sample_clean="${BASH_REMATCH[1]}"
            else sample_clean="$sample_base"; fi

            origine="${mapping[$sample_clean]}"
            [ -z "$origine" ] && origine="${mapping[$sample_name]}"
            [ -z "$origine" ] && origine="Inconnu_ou_Controle"
            # à décommenter UNIQUEMENT SI TISSU PROVIENNE DE LA MÊME COHORTE OU ORIGINE 
            #origine="IPMN"
            score_val="0.2"
            echo "--> Fichier trouvé : $(basename "$report") | Score : $score_val | Origine : $origine" >&2
                
            awk_output=$(awk -v samp="$sample_clean" \
                -v coh="TRIM" \
                -v ori="$origine" \
                -v scr="$score_val" \
                'BEGIN {
                    FS="\t"
                    is_bacteria = 0
                }
                /^#/ || /^%/ { next }
                {
                    reads = $2
                    minimizers = $4      
                    uniq_min = $5   
                    rank = $6       
                    taxid = $7      
                    species = $8    
                    
                    sub(/^[ \t]+/, "", species)

                    if (rank == "D" && taxid == 2) { is_bacteria = 1 }
                    else if (rank == "D" && taxid != 2) { is_bacteria = 0 }

                    if (taxid != 0 && taxid != 1) {
                        if (taxid == 9606) { categorie = "Humain" }
                        else if (is_bacteria == 1) { categorie = "Bacterie" }
                        else { categorie = "Autre_Vivant" }

                        if (rank == "S") {
                            print scr "," samp "," taxid ",species," reads "," minimizers "," uniq_min "," categorie "," ori "," coh "," species 
                        }
                    }
                }' "$report")

            nb_lignes=$(echo "$awk_output" | grep -c "^$sample_clean" || echo 0)
            echo "    ↳ Extraction réussie : $nb_lignes lignes ajoutées." >&2

            echo "$awk_output"
        done
    done
}

echo "Score,Sample,TaxID,Rank,Reads,Minimizers,Uniq_Minimizers,Categorie,ORIGINE,Methode,Species" > "$OUTPUT_FILE"

for DOSSIER in "${LISTE_DOSSIERS[@]}"; do
    echo "=================================================="
    echo "Traitement du dossier : $DOSSIER"
    echo "=================================================="
    if [ ! -d "$DOSSIER" ]; then
        echo "Erreur : Le dossier '$DOSSIER' n'existe pas." >&2
        continue
    fi
    process_files "$DOSSIER" | tr -d '\r' >> "$OUTPUT_FILE"
done

echo "=================================================="
echo "Extraction terminée. Fichier généré dans : $OUTPUT_FILE"